#include <map>
#include <iostream>

int main() {
    std::map<int, std::string> m = {{1, "A"}, {2, "B"}, {3, "C"}};

    // Erase key 2, returns 1 (size_type)
    size_t count = m.erase(2);

    // Erase key 99 (not present), returns 0
    size_t count_fail = m.erase(99);

    std::cout << "Removed elements: " << count << "\n";

    // The function does not throw
}
